function crabRows(big, legs, eyes, sp) {
  const rows = (big ? CRAB_BIG : CRAB_SMALL).map(r => r.split(''));
  const lr = (big ? LEGS_BIG : LEGS_SMALL)[legs ? 1 : 0];
  rows[rows.length - 1] = lr.split('');
  if (eyes === 'closed') {
    if (big) {
      rows[6] = rows[6].map(ch => ch === 'K' ? 'C' : ch);
      rows[7] = rows[7].map(ch => ch === 'K' ? 'O' : ch);
    } else rows[3] = rows[3].map(ch => ch === 'K' ? 'O' : ch);
  }
  const k = big ? 1 : 0;
  for (const key of ['fur', 'scarf', 'beret']) {
    if (!sp[key]) continue;
    for (const [x, y, ch] of OVERLAY[key][k]) rows[y][x] = ch;
  }
  return rows.map(r => r.join(''));
}
const spriteCache = new Map();
function crabPal(sp, hue, silhouette) {
  if (silhouette) { const s = '#6a5f80'; return { O: s, C: s, H: s, K: s, P: s, R: s, B: s }; }
