  return s;
}
const imgCache = new Map();
function crabImg(spId, stage, silhouette = false) {
  const key = `${spId}|${stage}|${silhouette}`;
  if (imgCache.has(key)) return imgCache.get(key);
  const big = stage > 0, s = crabSprite(spId, big, 0, 'open', 0, silhouette);
