  -webkit-tap-highlight-color: transparent;
}

#app {
  width: 100%;
  max-width: 760px;
  padding: 10px 16px calc(14px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* ---------- top bar ---------- */
#top { display: flex; align-items: center; gap: 12px; }
.kp {
  display: flex; align-items: center; gap: 6px;
  font-size: 22px;
  background: var(--btn);
  border: 3px solid var(--ink);
  box-shadow: 0 3px 0 var(--ink);
  padding: 2px 12px;
  transition: transform .08s;
}
.kp span { font-size: 13px; }
.kp.bump { transform: scale(1.08); }
.coin {
  width: 14px; height: 14px; display: inline-block;
  background: var(--gold);
  border: 2px solid #7a4a00;
  box-shadow: inset -2px -2px 0 #d9a520;
}
.meta { flex: 1; display: flex; flex-direction: column; font-size: 13px; line-height: 1.35; }

/* ---------- buttons ---------- */
button {
  font: inherit;
  color: var(--ink);
  background: var(--btn);
  border: 3px solid var(--ink);
  box-shadow: 0 3px 0 var(--ink);
  padding: 8px 6px;
  cursor: pointer;
  border-radius: 0;
}
button:active { transform: translateY(2px); box-shadow: 0 1px 0 var(--ink); }
button:disabled { opacity: .45; cursor: default; }
.icon { width: 42px; height: 42px; padding: 0; font-size: 20px; flex: none; }

